56	export function wrapReporterAsV2(reporter: Reporter | ReporterV2): ReporterV2 {
57	  try {
58	    if ('version' in reporter && reporter.version() === 'v2')
59	      return reporter as ReporterV2;
60	  } catch (e) {
61	  }
62	  return new ReporterV2Wrapper(reporter as Reporter);
63	}
