65	class ReporterV2Wrapper implements ReporterV2 {
66	  private _reporter: Reporter;
67	  private _deferred: { error?: TestError, stdout?: StdIOChunk, stderr?: StdIOChunk }[] | null = [];
68	  private _config!: FullConfig;
69	
70	  constructor(reporter: Reporter) {
71	    this._reporter = reporter;
72	  }
73	
74	  version(): 'v2' {
75	    return 'v2';
76	  }
77	
78	  onConfigure(config: FullConfig) {
79	    this._config = config;
80	  }
81	
82	  onBegin(suite: Suite) {
83	    this._reporter.onBegin?.(this._config, suite);
84	
85	    const deferred = this._deferred!;
86	    this._deferred = null;
87	    for (const item of deferred) {
88	      if (item.error)
89	        this.onError(item.error);
90	      if (item.stdout)
91	        this.onStdOut(item.stdout.chunk, item.stdout.test, item.stdout.result);
92	      if (item.stderr)
93	        this.onStdErr(item.stderr.chunk, item.stderr.test, item.stderr.result);
94	    }
