80	  async onEnd(result: { status: FullResult['status'] }) {
81	    if (!this._didBegin) {
82	      // onBegin was not reported, emit it.
83	      this.onBegin(new testNs.Suite('', 'root'));
84	    }
85	    return await this._reporter.onEnd?.({
86	      ...result,
