114	  private _addSnippetToTestErrors(test: TestCase, result: TestResult) {
115	    for (const error of result.errors)
116	      addLocationAndSnippetToError(this._config, error, test.location.file);
117	  }
118	
119	  private _addSnippetToStepError(test: TestCase, step: TestStep) {
