125	export function addLocationAndSnippetToError(config: FullConfig, error: TestError, file?: string) {
126	  if (error.stack && !error.location)
127	    error.location = prepareErrorStack(error.stack).location;
128	  const location = error.location;
129	  if (!location)
130	    return;
131	
132	  if (!!error.snippet)
133	    return;
134	
135	  try {
136	    const tokens = [];
137	    const source = fs.readFileSync(location.file, 'utf8');
138	    const codeFrame = babel.codeFrameColumns(source, { start: location }, { highlightCode: true });
139	    // Convert /var/folders to /private/var/folders on Mac.
140	    if (!file || fs.realpathSync(file) !== location.file) {
141	      tokens.push(internalScreen.colors.gray(`   at `) + `${relativeFilePath(internalScreen, config, location.file)}:${location.line}`);
142	      tokens.push('');
143	    }
144	    tokens.push(codeFrame);
145	    error.snippet = tokens.join('\n');
146	  } catch (e) {
147	    // Failed to read the source file - that's ok.
148	  }
149	}
